const student = $('Extract from File').first().json;
const modelItems = $('Get row(s) in sheet').all();
const model = (modelItems.length ? modelItems[modelItems.length - 1] : $('Get row(s) in sheet').first()).json;

// إجابات الطالب موجودة داخل row
const studentAnswers = student.row || [];

let correct = 0;
const totalQuestions = 10;

for (let i = 1; i <= totalQuestions; i++) {

    const studentAnswer = String(studentAnswers[i - 1] ?? '')
        .trim()
        .toUpperCase();

    const modelAnswer = String(model[`ANS_${i}`] ?? '')
        .trim()
        .toUpperCase();

    if (studentAnswer === modelAnswer) {
        correct++;
    }
}

const grade = correct;
const success = grade > 6;

return [{
    json: {
        student_id: model.sudent_id,
        subject_code: model.subject_code,
        lesson_id: model.lesson_id,
        file_name: model.FILE_NAME,

        correct_answers: correct,
        total_questions: totalQuestions,
        grade: grade,
         succed: grade > 6 ? 1 : 0,
        result: grade > 6 ? 'Pass' : 'Fail'

    }
}];

// =====================================================
// get_file
// تحديد الدرس التالي للطالب حسب student_progress
// =====================================================

// -----------------------------------------------------
// 1) قراءة رقم المادة الذي أرسله الطالب
// -----------------------------------------------------
const inputMessage = String(
  $('Latest message only').first()?.json?.message?.text || ''
).trim();

const subjectCode = inputMessage;

// -----------------------------------------------------
// 2) الحصول على student_id
// -----------------------------------------------------
let studentId = '';

try {
  studentId = String(
    $('Get row_by_chatid').first()?.json?.student_id ||
    $('Search Chat ID in Sheet').first()?.json?.student_id ||
    ''
  ).trim();
} catch (error) {
  studentId = '';
}

// -----------------------------------------------------
// 3) قراءة student_progress
// -----------------------------------------------------
const progressRows = $('GET_PROGRESS')
  .all()
  .map(item => item.json);

// -----------------------------------------------------
// 4) قراءة Lessons_Data
// -----------------------------------------------------
const lessonsRows = $('Get Lessons Data')
  .all()
  .map(item => item.json);

// -----------------------------------------------------
// دوال مساعدة
// -----------------------------------------------------

function normalize(value) {
  return String(value ?? '').trim();
}

function numberValue(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

// -----------------------------------------------------
// 5) استخراج دروس المادة المطلوبة فقط
// -----------------------------------------------------
const subjectLessons = lessonsRows.filter(row => {
  const rowSubjectCode = normalize(
    row.subject_code ?? row.SUBJECT_CODE
  );

  return rowSubjectCode === subjectCode;
});

// -----------------------------------------------------
// 6) إذا لم توجد المادة في Lessons_Data
// -----------------------------------------------------
if (subjectLessons.length === 0) {
  return [{
    json: {
      status: 'ERROR',
      message: 'كود المادة غير موجود في Lessons_Data',
      student_id: studentId,
      subject_code: subjectCode,
      subject_name: '',
      lesson_code: 0,
      lesson_name: '',
      file_name: ''
    }
  }];
}

// -----------------------------------------------------
// 7) استخراج اسم المادة
// -----------------------------------------------------
const subjectName =
  subjectLessons[0].subject ??
  subjectLessons[0].SUBJECT_NAME ??
  subjectLessons[0].subject_name ??
  '';

// -----------------------------------------------------
// 8) استخراج أكبر lesson_code موجود للمادة
// -----------------------------------------------------
const validLessonCodes = subjectLessons
  .map(row =>
    numberValue(row.lesson_code ?? row.LESSON_CODE)
  )
  .filter(code => code > 0);

const maxLessonCode =
  validLessonCodes.length > 0
    ? Math.max(...validLessonCodes)
    : 0;

// -----------------------------------------------------
// 9) استخراج سجلات الطالب لهذه المادة من student_progress
// -----------------------------------------------------
const studentSubjectProgress = progressRows.filter(row => {

  // الشيت عندك قد يحتوي sudent_id بالخطأ
  // أو student_id
  const rowStudentId = normalize(
    row.sudent_id ?? row.student_id
  );

  const rowSubjectCode = normalize(
    row.subject_code ?? row.SUBJECT_CODE
  );

  return (
    rowStudentId === studentId &&
    rowSubjectCode === subjectCode
  );
});

// -----------------------------------------------------
// 10) تحديد الدرس التالي
// -----------------------------------------------------
let nextLessonCode = 1;

// -----------------------------------------------------
// الحالة الأولى:
// لا يوجد أي سجل للطالب في هذه المادة
// => يبدأ من الدرس رقم 1
// -----------------------------------------------------
if (studentSubjectProgress.length === 0) {

  nextLessonCode = 1;

} else {

  // ---------------------------------------------------
  // أخذ الدروس التي succeed = 1 فقط
  // ---------------------------------------------------
  const successfulLessons = studentSubjectProgress.filter(row => {

    const succeed = normalize(row.succeed ?? row.succed).toLowerCase();

    return (
      succeed === '1' ||
      succeed === 'true'
    );
  });

  // ---------------------------------------------------
  // إذا كان هناك دروس ناجحة
  // => أكبر lesson_code + 1
  // ---------------------------------------------------
  if (successfulLessons.length > 0) {

    const successfulCodes = successfulLessons
      .map(row =>
        numberValue(
          row.lesson_code ?? row.lesson_id ?? row.LESSON_CODE
        )
      )
      .filter(code => code > 0);

    if (successfulCodes.length > 0) {

      const maxSucceededLesson =
        Math.max(...successfulCodes);

      nextLessonCode = maxSucceededLesson + 1;

    } else {

      nextLessonCode = 1;
    }

  } else {

    // توجد سجلات للطالب والمادة
    // ولكن لم ينجح في أي درس
    nextLessonCode = 1;
  }
}

// -----------------------------------------------------
// 11) التحقق هل الطالب أتم المنهج
// -----------------------------------------------------
if (
  maxLessonCode > 0 &&
  nextLessonCode > maxLessonCode
) {

  return [{
    json: {
      status: 'COMPLETED',
      message: 'لقد أتممت منهج المادة',
      student_id: studentId,
      subject_code: subjectCode,
      subject_name: subjectName,
      lesson_code: 0,
      lesson_name: '',
      file_name: ''
    }
  }];
}

// -----------------------------------------------------
// 12) البحث عن بيانات الدرس المطلوب
// -----------------------------------------------------
const targetLesson = subjectLessons.find(row => {

  const lessonCode = numberValue(
    row.lesson_code ?? row.LESSON_CODE
  );

  return lessonCode === nextLessonCode;
});

// -----------------------------------------------------
// 13) حماية إضافية:
// إذا كان رقم الدرس محسوباً لكن غير موجود فعلياً
// في Lessons_Data
// -----------------------------------------------------
if (!targetLesson) {

  return [{
    json: {
      status: 'ERROR',
      message: 'رقم الدرس المطلوب غير موجود في Lessons_Data',
      student_id: studentId,
      subject_code: subjectCode,
      subject_name: subjectName,
      lesson_code: nextLessonCode,
      lesson_name: '',
      file_name: ''
    }
  }];
}

// -----------------------------------------------------
// 14) استخراج بيانات الدرس
// -----------------------------------------------------
const lessonName =
  targetLesson.lesson_name ??
  targetLesson.lesson ??
  targetLesson.LESSON_NAME ??
  '';

const fileName =
  targetLesson.file_name ??
  targetLesson.FILE_NAME ??
  '';

// -----------------------------------------------------
// 15) النتيجة النهائية
// -----------------------------------------------------
return [{
  json: {
    status: 'IN_PROGRESS',
    message: 'تم استخراج الدرس بنجاح',

    student_id: studentId,

    subject_code: subjectCode,
    subject_name: subjectName,

    lesson_code: nextLessonCode,
    lesson_name: lessonName,

    file_name: fileName
  }
}];

