const input = $input.first()?.json ?? {};

// =====================================================
// 1. Get AI Agent output
// =====================================================

let rawText = input.output ?? input.text ?? "";

if (typeof rawText !== "string") {
  rawText = JSON.stringify(rawText);
}

rawText = rawText.trim();

// =====================================================
// 2. Initialize variables
// =====================================================

let lessonMarkdown = "";
let modelAnswers = "";

// =====================================================
// 3. Clean Markdown / JSON code fences
// =====================================================

let cleanJsonText = rawText
  .replace(/^\s*```json\s*/i, "")
  .replace(/^\s*```\s*/i, "")
  .replace(/\s*```\s*$/i, "")
  .trim();

// =====================================================
// 4. Parse AI Agent JSON response
// =====================================================

try {

  const parsedData = JSON.parse(cleanJsonText);

  lessonMarkdown = parsedData.lesson_markdown ?? "";
  modelAnswers = parsedData.model_answers ?? "";

} catch (error) {

  // ---------------------------------------------------
  // Fallback if AI returned malformed JSON
  // ---------------------------------------------------

  lessonMarkdown = rawText;

  modelAnswers = "";

  // Try to extract model_answers from the raw response
  const answerMatch = rawText.match(
    /["']?model_answers["']?\s*:\s*["']([\s\S]*?)["']\s*[,}]/i
  );

  if (answerMatch) {
    modelAnswers = answerMatch[1];
  }
}

// =====================================================
// 5. Clean lesson_markdown if JSON accidentally remains
// =====================================================

if (typeof lessonMarkdown !== "string") {
  lessonMarkdown = JSON.stringify(lessonMarkdown);
}

lessonMarkdown = lessonMarkdown
  .replace(/^```(?:markdown)?\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// =====================================================
// 6. Get student information
// =====================================================

let studentName = "Student";
let studentEmail = "";
let chatId = "";

try {

  const student = $("CHECH_WAITNG").first().json;

  studentName = student.student_name ?? studentName;

  studentEmail = student.student_email ?? "";

  chatId = student.telegram_chat_id ?? "";

} catch (error) {

  // Keep default values
}

// =====================================================
// 7. Get lesson information
// =====================================================

let lessonName = "Lesson";

try {

  const lesson = $("Get Lessons Data").first().json;

  studentEmail =
    studentEmail ||
    lesson.student_email ||
    "";

  lessonName =
    lesson.lesson_name ??
    lessonName;

} catch (error) {

  // Keep existing values
}

// =====================================================
// 8. Prepare ANS_1 ... ANS_10
// =====================================================

const answers = {};

for (let i = 1; i <= 10; i++) {
  answers[`ANS_${i}`] = "";
}

// =====================================================
// 9. Normalize model_answers
// =====================================================

let answerText = String(modelAnswers ?? "")

  // Convert escaped newlines to spaces
  .replace(/\\n/g, " ")

  // Convert real newlines to spaces
  .replace(/\r?\n/g, " ")

  // Remove code fences
  .replace(/```/g, "")

  .trim();

// =====================================================
// 10. Extract answers
//
// Supported formats:
//
// ans_1: A
// ans_1 = A
// ans_1 - A
// ANS_1: A
// ans 1: A
// answer_1: A
// =====================================================

const answerRegex =
  /(?:ans(?:wer)?)[_\s-]*(\d{1,2})\s*[:=\-]\s*([ABCD])\b/gi;

let match;

while ((match = answerRegex.exec(answerText)) !== null) {

  const number = Number(match[1]);

  const answer = match[2].toUpperCase();

  if (number >= 1 && number <= 10) {

    answers[`ANS_${number}`] = answer;

  }
}

// =====================================================
// 11. Additional fallback
//
// If Gemini returns something like:
//
// 1: A, 2: B, 3: C...
//
// try to extract it as well.
// =====================================================

for (let i = 1; i <= 10; i++) {

  if (answers[`ANS_${i}`] !== "") {
    continue;
  }

  const simpleRegex =
    new RegExp(
      `(?:^|[,;\\s])${i}\\s*[:=\\-]\\s*([ABCD])\\b`,
      "i"
    );

  const simpleMatch = answerText.match(simpleRegex);

  if (simpleMatch) {

    answers[`ANS_${i}`] =
      simpleMatch[1].toUpperCase();

  }
}

// =====================================================
// 12. Return all data
// =====================================================

return [
  {
    json: {

      // Student information
      student_name: studentName,

      student_email: studentEmail,

      lesson_name: lessonName,

      chat_id: chatId,

      // Lesson content
      lesson_markdown: lessonMarkdown,

      // Complete model answer string
      model_answers: modelAnswers,

      // Individual answers for Google Sheets
      ...answers

    }
  }
];

