// --------------------------------------------------
// 2. HTML escaping
// --------------------------------------------------

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// --------------------------------------------------
// 3. Inline Markdown
// --------------------------------------------------

function inlineMarkdown(text) {

  let s = escapeHtml(text);

  // Bold
  s = s.replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
  s = s.replace(/__(.+?)__/g, "<strong>$1</strong>");

  // Italic
  s = s.replace(/\*(.+?)\*/g, "<em>$1</em>");
  s = s.replace(/_(.+?)_/g, "<em>$1</em>");

  // Code
  s = s.replace(/`([^`]+)`/g, "<code>$1</code>");

  return s;
}

// --------------------------------------------------
// 4. Markdown → HTML
// --------------------------------------------------

function markdownToHtml(md) {

  const lines = md
    .replace(/\r\n/g, "\n")
    .split("\n");

  const html = [];

  let paragraph = [];
  let listType = null;

  function flushParagraph() {

    if (!paragraph.length) return;

    const text = paragraph
      .map(line => inlineMarkdown(line))
      .join(" ");

    html.push(`<p>${text}</p>`);

    paragraph = [];
  }

  function closeList() {

    if (listType) {
      html.push(`</${listType}>`);
      listType = null;
    }
  }

  for (let rawLine of lines) {

    const line = rawLine.trim();

    // Empty line
    if (!line) {
      flushParagraph();
      closeList();
      continue;
    }

    // Horizontal line
    if (/^(-{3,}|\*{3,})$/.test(line)) {

      flushParagraph();
      closeList();

      html.push("<hr>");

      continue;
    }

    // H1
    let match = line.match(/^#\s+(.+)$/);

    if (match) {

      flushParagraph();
      closeList();

      html.push(
        `<h1>${inlineMarkdown(match[1])}</h1>`
      );

      continue;
    }

    // H2
    match = line.match(/^##\s+(.+)$/);

    if (match) {

      flushParagraph();
      closeList();

      html.push(
        `<h2>${inlineMarkdown(match[1])}</h2>`
      );

      continue;
    }

    // H3
    match = line.match(/^###\s+(.+)$/);

    if (match) {

      flushParagraph();
      closeList();

      html.push(
        `<h3>${inlineMarkdown(match[1])}</h3>`
      );

      continue;
    }

    // Bullet list
    match = line.match(/^[-*+]\s+(.+)$/);

    if (match) {

      flushParagraph();

      if (listType !== "ul") {

        closeList();

        html.push("<ul>");

        listType = "ul";
      }

      html.push(
        `<li>${inlineMarkdown(match[1])}</li>`
      );

      continue;
    }

    // Numbered list
    match = line.match(/^\d+[.)]\s+(.+)$/);

    if (match) {

      flushParagraph();

      if (listType !== "ol") {

        closeList();

        html.push("<ol>");

        listType = "ol";
      }

      html.push(
        `<li>${inlineMarkdown(match[1])}</li>`
      );

      continue;
    }

    // MCQ options
    match = line.match(/^([A-D])[\.)]\s+(.+)$/i);

    if (match) {

      flushParagraph();
      closeList();

      html.push(`
        <div class="option">
          <span class="option-letter">${match[1].toUpperCase()}</span>
          <span>${inlineMarkdown(match[2])}</span>
        </div>
      `);

      continue;
    }

    // Normal text
    closeList();

    paragraph.push(line);
  }

  flushParagraph();
  closeList();

  return html.join("\n");
}

